{"version":3,"file":"index.node.esm.js","sources":["../../src/core/error.ts","../../src/core/version.ts","../../src/logger.ts","../../src/network/transport.ts","../../src/network/rest/fetch.ts","../../src/util/url.ts","../../src/network/rest/restTransport.ts","../../src/network/stream/streamTransport.ts","../../src/network/stream/websocket.ts","../../src/cache/EntityDataObject.ts","../../src/cache/InMemoryCacheProvider.ts","../../src/cache/EntityNode.ts","../../src/cache/ResultTree.ts","../../src/cache/ImpactedQueryRefsAccumulator.ts","../../src/cache/ResultTreeProcessor.ts","../../src/cache/Cache.ts","../../src/core/AppCheckTokenProvider.ts","../../src/core/FirebaseAuthProvider.ts","../../src/api/Reference.ts","../../src/cache/cacheUtils.ts","../../src/util/encoder.ts","../../src/core/query/QueryManager.ts","../../src/network/manager.ts","../../src/api/Mutation.ts","../../src/api/DataConnect.ts","../../src/register.ts","../../src/core/query/queryOptions.ts","../../src/api/query.ts","../../src/util/validateArgs.ts","../../src/core/query/subscribe.ts","../../src/index.node.ts"],"sourcesContent":["/**\n * @license\n * Copyright 2024 Google LLC\n *\n * Licensed under the Apache License, Version 2.0 (the \"License\");\n * you may not use this file except in compliance with the License.\n * You may obtain a copy of the License at\n *\n *   http://www.apache.org/licenses/LICENSE-2.0\n *\n * Unless required by applicable law or agreed to in writing, software\n * distributed under the License is distributed on an \"AS IS\" BASIS,\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n * See the License for the specific language governing permissions and\n * limitations under the License.\n */\n\nimport { FirebaseError } from '@firebase/util';\n\nexport type DataConnectErrorCode =\n  | 'other'\n  | 'already-initialized'\n  | 'not-initialized'\n  | 'not-supported'\n  | 'invalid-argument'\n  | 'partial-error'\n  | 'unauthorized';\n\nexport type Code = DataConnectErrorCode;\n\nexport const Code = {\n  OTHER: 'other' as DataConnectErrorCode,\n  ALREADY_INITIALIZED: 'already-initialized' as DataConnectErrorCode,\n  NOT_INITIALIZED: 'not-initialized' as DataConnectErrorCode,\n  NOT_SUPPORTED: 'not-supported' as DataConnectErrorCode,\n  INVALID_ARGUMENT: 'invalid-argument' as DataConnectErrorCode,\n  PARTIAL_ERROR: 'partial-error' as DataConnectErrorCode,\n  UNAUTHORIZED: 'unauthorized' as DataConnectErrorCode\n};\n\n/** An error returned by a DataConnect operation. */\nexport class DataConnectError extends FirebaseError {\n  /** @internal */\n  readonly name: string = 'DataConnectError';\n\n  constructor(code: Code, message: string) {\n    super(code, message);\n\n    // Ensure the instanceof operator works as expected on subclasses of Error.\n    // See https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Error#custom_error_types\n    // and https://www.typescriptlang.org/docs/handbook/release-notes/typescript-2-2.html#support-for-newtarget\n    Object.setPrototypeOf(this, DataConnectError.prototype);\n  }\n\n  /** @internal */\n  toString(): string {\n    return `${this.name}[code=${this.code}]: ${this.message}`;\n  }\n}\n\n/** An error returned by a DataConnect operation. */\nexport class DataConnectOperationError extends DataConnectError {\n  /** @internal */\n  readonly name: string = 'DataConnectOperationError';\n\n  /** The response received from the backend. */\n  readonly response: DataConnectOperationFailureResponse;\n\n  /** @hideconstructor */\n  constructor(message: string, response: DataConnectOperationFailureResponse) {\n    super(Code.PARTIAL_ERROR, message);\n    this.response = response;\n  }\n}\n\nexport interface DataConnectOperationFailureResponse {\n  // The \"data\" provided by the backend in the response message.\n  //\n  // Will be `undefined` if no \"data\" was provided in the response message.\n  // Otherwise, will be `null` if `null` was explicitly specified as the \"data\"\n  // in the response message. Otherwise, will be the value of the \"data\"\n  // specified as the \"data\" in the response message\n  readonly data?: Record<string, unknown> | null;\n\n  // The list of errors provided by the backend in the response message.\n  readonly errors: DataConnectOperationFailureResponseErrorInfo[];\n}\n\n// Information about the error, as provided in the response from the backend.\n// See https://spec.graphql.org/draft/#sec-Errors\nexport interface DataConnectOperationFailureResponseErrorInfo {\n  // The error message.\n  readonly message: string;\n\n  // The path of the field in the response data to which this error relates.\n  // String values in this array refer to field names. Numeric values in this\n  // array always satisfy `Number.isInteger()` and refer to the index in an\n  // array.\n  readonly path: Array<string | number>;\n}\n","/**\n * @license\n * Copyright 2024 Google LLC\n *\n * Licensed under the Apache License, Version 2.0 (the \"License\");\n * you may not use this file except in compliance with the License.\n * You may obtain a copy of the License at\n *\n *   http://www.apache.org/licenses/LICENSE-2.0\n *\n * Unless required by applicable law or agreed to in writing, software\n * distributed under the License is distributed on an \"AS IS\" BASIS,\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n * See the License for the specific language governing permissions and\n * limitations under the License.\n */\n\n/** The semver (www.semver.org) version of the SDK. */\nexport let SDK_VERSION = '';\n\n/**\n * SDK_VERSION should be set before any database instance is created\n * @internal\n */\nexport function setSDKVersion(version: string): void {\n  SDK_VERSION = version;\n}\n","/**\n * @license\n * Copyright 2024 Google LLC\n *\n * Licensed under the Apache License, Version 2.0 (the \"License\");\n * you may not use this file except in compliance with the License.\n * You may obtain a copy of the License at\n *\n *   http://www.apache.org/licenses/LICENSE-2.0\n *\n * Unless required by applicable law or agreed to in writing, software\n * distributed under the License is distributed on an \"AS IS\" BASIS,\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n * See the License for the specific language governing permissions and\n * limitations under the License.\n */\nimport { Logger, LogLevelString } from '@firebase/logger';\n\nimport { SDK_VERSION } from './core/version';\n\nconst logger = new Logger('@firebase/data-connect');\nexport function setLogLevel(logLevel: LogLevelString): void {\n  logger.setLogLevel(logLevel);\n}\nexport function logDebug(msg: string): void {\n  logger.debug(`DataConnect (${SDK_VERSION}): ${msg}`);\n}\n\nexport function logError(msg: string): void {\n  logger.error(`DataConnect (${SDK_VERSION}): ${msg}`);\n}\n","/**\n * @license\n * Copyright 2024 Google LLC\n *\n * Licensed under the Apache License, Version 2.0 (the \"License\");\n * you may not use this file except in compliance with the License.\n * You may obtain a copy of the License at\n *\n *   http://www.apache.org/licenses/LICENSE-2.0\n *\n * Unless required by applicable law or agreed to in writing, software\n * distributed under the License is distributed on an \"AS IS\" BASIS,\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n * See the License for the specific language governing permissions and\n * limitations under the License.\n */\n\nimport { DataConnectOptions, TransportOptions } from '../api/DataConnect';\nimport { AppCheckTokenProvider } from '../core/AppCheckTokenProvider';\nimport { Code, DataConnectError } from '../core/error';\nimport { AuthTokenProvider } from '../core/FirebaseAuthProvider';\nimport { SDK_VERSION } from '../core/version';\nimport { logDebug } from '../logger';\n\n/**\n * enum representing different flavors of the SDK used by developers\n * use the CallerSdkType for type-checking, and the CallerSdkTypeEnum for value-checking/assigning\n */\nexport type CallerSdkType =\n  | 'Base' // Core JS SDK\n  | 'Generated' // Generated JS SDK\n  | 'TanstackReactCore' // Tanstack non-generated React SDK\n  | 'GeneratedReact' // Generated React SDK\n  | 'TanstackAngularCore' // Tanstack non-generated Angular SDK\n  | 'GeneratedAngular'; // Generated Angular SDK\nexport const CallerSdkTypeEnum = {\n  Base: 'Base', // Core JS SDK\n  Generated: 'Generated', // Generated JS SDK\n  TanstackReactCore: 'TanstackReactCore', // Tanstack non-generated React SDK\n  GeneratedReact: 'GeneratedReact', // Tanstack non-generated Angular SDK\n  TanstackAngularCore: 'TanstackAngularCore', // Tanstack non-generated Angular SDK\n  GeneratedAngular: 'GeneratedAngular' // Generated Angular SDK\n} as const;\n\nexport interface DataConnectEntityArray {\n  entityIds: string[];\n}\n\nexport interface DataConnectSingleEntity {\n  entityId: string;\n}\n\nexport type DataConnectExtension = {\n  path: Array<string | number>;\n} & (DataConnectEntityArray | DataConnectSingleEntity);\n\n/** @internal */\nexport interface DataConnectMaxAge {\n  maxAge: string;\n}\n\n/** @internal */\nexport type DataConnectExtensionWithMaxAge = {\n  path: Array<string | number>;\n} & (DataConnectEntityArray | DataConnectSingleEntity | DataConnectMaxAge);\n\nexport interface Extensions {\n  dataConnect?: DataConnectExtension[];\n}\n\n/** @internal */\nexport interface ExtensionsWithMaxAge {\n  dataConnect?: DataConnectExtensionWithMaxAge[];\n}\n\n/** @internal */\nexport interface DataConnectResponse<T> {\n  data: T;\n  errors: Error[];\n  extensions: Extensions;\n}\n\n/** @internal */\nexport interface DataConnectResponseWithMaxAge<T> {\n  data: T;\n  errors: Error[];\n  extensions: ExtensionsWithMaxAge;\n}\n\n/**\n * Observer defined by the Query Layer for receiving notifications from the Transport Layer.\n * @internal\n */\nexport interface SubscribeObserver<Data> {\n  onData(response: DataConnectResponse<Data>): Promise<void> | void;\n  onDisconnect(code: string, reason: string): void;\n  onError(error: Error): void;\n}\n\n/**\n * Interface defining the external API of the transport layer.\n * @internal\n */\nexport interface DataConnectTransportInterface {\n  /**\n   * Invoke a query execution request.\n   * @param queryName The name of the query to execute.\n   * @param body The variables associated with the query.\n   * @returns A promise resolving to the DataConnectResponse.\n   */\n  invokeQuery<Data, Variables>(\n    queryName: string,\n    body?: Variables\n  ): Promise<DataConnectResponseWithMaxAge<Data>>;\n\n  /**\n   * Invoke a mutation execution request.\n   * @param queryName The name of the mutation to execute.\n   * @param body The variables associated with the mutation.\n   * @returns A promise resolving to the DataConnectResponse.\n   */\n  invokeMutation<Data, Variables>(\n    queryName: string,\n    body?: Variables\n  ): Promise<DataConnectResponse<Data>>;\n\n  /**\n   * Subscribes to a query to receive push notifications of updates.\n   * @param observer the observer passed to the transport layer to notify the query layer of events.\n   * @param queryName The name of the query to subscribe to.\n   * @param body The variables associated with the subscription.\n   */\n  invokeSubscribe<Data, Variables>(\n    observer: SubscribeObserver<Data>,\n    queryName: string,\n    body?: Variables\n  ): void;\n\n  /**\n   * Unsubscribes from an active subscription.\n   * @param queryName The name of the query to unsubscribe from.\n   * @param body The variables associated with the subscription.\n   */\n  invokeUnsubscribe<Variables>(queryName: string, body?: Variables): void;\n\n  /**\n   * Configures the transport to use a local Data Connect emulator.\n   * @param host The host address of the emulator (e.g., '127.0.0.1').\n   * @param port The port number the emulator is listening on.\n   * @param sslEnabled Whether to use SSL (HTTPS/WSS) for the emulator connection.\n   */\n  useEmulator(host: string, port?: number, sslEnabled?: boolean): void;\n\n  /**\n   * Callback invoked when the Firebase Auth token is refreshed or changed. Note that this callback\n   * is called immediately asynchronously when the Auth Provider is initialized to provide\n   * the initial auth state.\n   * @param token The new access token or null if signed out.\n   */\n  onAuthTokenChanged: (token: string | null) => void;\n\n  /**\n   * Internal method to set the SDK type for metrics and logging purposes.\n   * @param callerSdkType The type of SDK making the call (e.g., generated vs base).\n   */\n  _setCallerSdkType(callerSdkType: CallerSdkType): void;\n}\n\n/**\n * Type signature of a transport class constructor.\n * @internal\n */\nexport type TransportClass = new (\n  options: DataConnectOptions,\n  apiKey?: string,\n  appId?: string,\n  authProvider?: AuthTokenProvider,\n  appCheckProvider?: AppCheckTokenProvider,\n  transportOptions?: TransportOptions,\n  _isUsingGen?: boolean,\n  _callerSdkType?: CallerSdkType\n) => DataConnectTransportInterface;\n\n/**\n * Constructs the value for the X-Goog-Api-Client header\n * @internal\n */\nexport function getGoogApiClientValue(\n  isUsingGen: boolean,\n  callerSdkType: CallerSdkType\n): string {\n  let str = 'gl-js/ fire/' + SDK_VERSION;\n  if (\n    callerSdkType !== CallerSdkTypeEnum.Base &&\n    callerSdkType !== CallerSdkTypeEnum.Generated\n  ) {\n    str += ' js/' + callerSdkType.toLowerCase();\n  } else if (isUsingGen || callerSdkType === CallerSdkTypeEnum.Generated) {\n    str += ' js/gen';\n  }\n  return str;\n}\n\n/**\n * The base class for all DataConnectTransportInterface implementations. Handles common logic such as\n * URL construction, auth token management, and emulator usage. Concrete transport implementations\n * should extend this class and implement the abstract {@link DataConnectTransportInterface} methods.\n * @internal\n */\nexport abstract class AbstractDataConnectTransport implements DataConnectTransportInterface {\n  protected _host = '';\n  protected _port: number | undefined;\n  protected _location = 'l';\n  protected _connectorName = '';\n  /** The resource path for requests from this Data Connect instance. */\n  protected _connectorResourcePath: string;\n  protected _secure = true;\n  protected _project = 'p';\n  protected _serviceName: string;\n  protected _authToken: string | null = null;\n  protected _appCheckToken: string | null | undefined = null;\n  protected _lastToken: string | null = null;\n  protected _isUsingEmulator = false;\n\n  constructor(\n    options: DataConnectOptions,\n    protected apiKey?: string | undefined,\n    protected appId?: string | null,\n    protected authProvider?: AuthTokenProvider | undefined,\n    protected appCheckProvider?: AppCheckTokenProvider | undefined,\n    transportOptions?: TransportOptions | undefined,\n    protected _isUsingGen = false,\n    protected _callerSdkType: CallerSdkType = CallerSdkTypeEnum.Base\n  ) {\n    if (transportOptions) {\n      if (typeof transportOptions.port === 'number') {\n        this._port = transportOptions.port;\n      }\n      if (typeof transportOptions.sslEnabled !== 'undefined') {\n        this._secure = transportOptions.sslEnabled;\n      }\n      this._host = transportOptions.host;\n    }\n    const { location, projectId: project, connector, service } = options;\n    if (location) {\n      this._location = location;\n    }\n    if (project) {\n      this._project = project;\n    }\n    this._serviceName = service;\n    if (!connector) {\n      throw new DataConnectError(\n        Code.INVALID_ARGUMENT,\n        'Connector Name required!'\n      );\n    }\n    this._connectorName = connector;\n    this._connectorResourcePath = `projects/${this._project}/locations/${this._location}/services/${this._serviceName}/connectors/${this._connectorName}`;\n    this.authProvider?.addTokenChangeListener(token => {\n      logDebug(`New Token Available: ${token}`);\n      this.onAuthTokenChanged(token);\n    });\n    this.appCheckProvider?.addTokenChangeListener(result => {\n      const { token } = result;\n      logDebug(`New App Check Token Available: ${token}`);\n      this._appCheckToken = token;\n    });\n  }\n\n  /** Get the endpoint URL this transport should use to communicate with the backend. */\n  abstract get endpointUrl(): string;\n\n  useEmulator(host: string, port?: number, isSecure?: boolean): void {\n    this._host = host;\n    this._isUsingEmulator = true;\n    if (typeof port === 'number') {\n      this._port = port;\n    }\n    if (typeof isSecure !== 'undefined') {\n      this._secure = isSecure;\n    }\n  }\n\n  async getWithAuth(forceToken = false): Promise<string | null> {\n    let starterPromise: Promise<string | null> = new Promise(resolve =>\n      resolve(this._authToken)\n    );\n    if (this.appCheckProvider) {\n      const appCheckToken = await this.appCheckProvider.getToken();\n      if (appCheckToken) {\n        this._appCheckToken = appCheckToken.token;\n      }\n    }\n    if (this.authProvider) {\n      starterPromise = this.authProvider\n        .getToken(/*forceToken=*/ forceToken)\n        .then(data => {\n          if (!data) {\n            return null;\n          }\n          this._authToken = data.accessToken;\n          return this._authToken;\n        });\n    } else {\n      starterPromise = new Promise(resolve => resolve(''));\n    }\n    return starterPromise;\n  }\n\n  async withRetry<T>(\n    promiseFactory: () => Promise<DataConnectResponse<T>>,\n    retry = false\n  ): Promise<DataConnectResponse<T>> {\n    let isNewToken = false;\n    return this.getWithAuth(retry)\n      .then(res => {\n        isNewToken = this._lastToken !== res;\n        this._lastToken = res;\n        return res;\n      })\n      .then(promiseFactory)\n      .catch(err => {\n        // Only retry if the result is unauthorized and the last token isn't the same as the new one.\n        if (\n          'code' in err &&\n          err.code === Code.UNAUTHORIZED &&\n          !retry &&\n          isNewToken\n        ) {\n          logDebug('Retrying due to unauthorized');\n          return this.withRetry(promiseFactory, true);\n        }\n        throw err;\n      });\n  }\n\n  _setLastToken(lastToken: string | null): void {\n    this._lastToken = lastToken;\n  }\n\n  abstract invokeQuery<Data, Variables>(\n    queryName: string,\n    body?: Variables\n  ): Promise<DataConnectResponseWithMaxAge<Data>>;\n\n  abstract invokeMutation<Data, Variables>(\n    queryName: string,\n    body?: Variables\n  ): Promise<DataConnectResponse<Data>>;\n\n  abstract invokeSubscribe<Data, Variables>(\n    observer: SubscribeObserver<Data>,\n    queryName: string,\n    body?: Variables\n  ): void;\n\n  abstract invokeUnsubscribe<Variables>(\n    queryName: string,\n    variables: Variables\n  ): void;\n\n  abstract onAuthTokenChanged(newToken: string | null): void;\n\n  _setCallerSdkType(callerSdkType: CallerSdkType): void {\n    this._callerSdkType = callerSdkType;\n  }\n}\n","/**\n * @license\n * Copyright 2024 Google LLC\n *\n * Licensed under the Apache License, Version 2.0 (the \"License\");\n * you may not use this file except in compliance with the License.\n * You may obtain a copy of the License at\n *\n *   http://www.apache.org/licenses/LICENSE-2.0\n *\n * Unless required by applicable law or agreed to in writing, software\n * distributed under the License is distributed on an \"AS IS\" BASIS,\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n * See the License for the specific language governing permissions and\n * limitations under the License.\n */\n\nimport { isCloudWorkstation } from '@firebase/util';\n\nimport {\n  CallerSdkType,\n  CallerSdkTypeEnum,\n  DataConnectResponse,\n  Extensions\n} from '..';\nimport {\n  Code,\n  DataConnectError,\n  DataConnectOperationError,\n  DataConnectOperationFailureResponse\n} from '../../core/error';\nimport { SDK_VERSION } from '../../core/version';\nimport { logError } from '../../logger';\n\n/** The fetch implementation to be used by the {@link RESTTransport}. */\nlet connectFetch: typeof fetch | null = globalThis.fetch;\n\n/**\n * This function is ONLY used for testing and for ensuring compatability in environments which may\n * be using a poyfill and/or bundlers. It should not be called by users of the Firebase JS SDK.\n * @internal\n */\nexport function initializeFetch(fetchImpl: typeof fetch): void {\n  connectFetch = fetchImpl;\n}\n\nfunction getGoogApiClientValue(\n  _isUsingGen: boolean,\n  _callerSdkType: CallerSdkType\n): string {\n  let str = 'gl-js/ fire/' + SDK_VERSION;\n  if (\n    _callerSdkType !== CallerSdkTypeEnum.Base &&\n    _callerSdkType !== CallerSdkTypeEnum.Generated\n  ) {\n    str += ' js/' + _callerSdkType.toLowerCase();\n  } else if (_isUsingGen || _callerSdkType === CallerSdkTypeEnum.Generated) {\n    str += ' js/gen';\n  }\n  return str;\n}\nexport interface DataConnectFetchBody<Variables> {\n  name: string;\n  operationName: string;\n  variables: Variables;\n}\nexport async function dcFetch<Data, Variables>(\n  url: string,\n  body: DataConnectFetchBody<Variables>,\n  { signal }: AbortController,\n  appId: string | null | undefined,\n  accessToken: string | null,\n  appCheckToken: string | null | undefined,\n  _isUsingGen: boolean,\n  _callerSdkType: CallerSdkType,\n  _isUsingEmulator: boolean\n): Promise<DataConnectResponse<Data>> {\n  if (!connectFetch) {\n    throw new DataConnectError(Code.OTHER, 'No Fetch Implementation detected!');\n  }\n  const headers: HeadersInit = {\n    'Content-Type': 'application/json',\n    'X-Goog-Api-Client': getGoogApiClientValue(_isUsingGen, _callerSdkType),\n    'X-Client-Version': `web/${SDK_VERSION}`\n  };\n  if (accessToken) {\n    headers['X-Firebase-Auth-Token'] = accessToken;\n  }\n  if (appId) {\n    headers['x-firebase-gmpid'] = appId;\n  }\n  if (appCheckToken) {\n    headers['X-Firebase-AppCheck'] = appCheckToken;\n  }\n  const bodyStr = JSON.stringify(body);\n  const fetchOptions: RequestInit = {\n    body: bodyStr,\n    method: 'POST',\n    headers,\n    signal\n  };\n  if (isCloudWorkstation(url) && _isUsingEmulator) {\n    fetchOptions.credentials = 'include';\n  }\n\n  let response: Response;\n  try {\n    response = await connectFetch(url, fetchOptions);\n  } catch (err) {\n    const message =\n      err && typeof err === 'object' && 'message' in err\n        ? (err as unknown as Record<string, unknown>)['message']\n        : String(err);\n    throw new DataConnectError(Code.OTHER, 'Failed to fetch: ' + message);\n  }\n  let jsonResponse: JsonResponse<Data>;\n  try {\n    jsonResponse = await response.json();\n  } catch (e) {\n    const message =\n      e && typeof e === 'object' && 'message' in e\n        ? (e as unknown as Record<string, unknown>)['message']\n        : String(e);\n    throw new DataConnectError(\n      Code.OTHER,\n      'Failed to parse JSON response: ' + message\n    );\n  }\n  const message = getErrorMessage(jsonResponse);\n  if (response.status >= 400) {\n    logError('Error while performing request: ' + JSON.stringify(jsonResponse));\n    if (response.status === 401) {\n      throw new DataConnectError(Code.UNAUTHORIZED, message);\n    }\n    throw new DataConnectError(Code.OTHER, message);\n  }\n  if (jsonResponse.errors && jsonResponse.errors.length) {\n    const stringified = JSON.stringify(jsonResponse.errors);\n    const failureResponse: DataConnectOperationFailureResponse = {\n      errors: jsonResponse.errors,\n      data: jsonResponse.data as Record<string, unknown>\n    };\n    throw new DataConnectOperationError(\n      'DataConnect error while performing request: ' + stringified,\n      failureResponse\n    );\n  }\n  if (!jsonResponse.extensions) {\n    jsonResponse.extensions = {\n      dataConnect: []\n    };\n  }\n  return jsonResponse as DataConnectResponse<Data>;\n}\ninterface JsonResponse<Data> {\n  message?: string;\n  errors: [];\n  data: Record<string, unknown> | Data | null;\n  extensions?: Extensions;\n}\nfunction getErrorMessage(obj: JsonResponse<unknown>): string {\n  if ('message' in obj && obj.message) {\n    return obj.message;\n  }\n  return JSON.stringify(obj);\n}\n","/**\n * @license\n * Copyright 2024 Google LLC\n *\n * Licensed under the Apache License, Version 2.0 (the \"License\");\n * you may not use this file except in compliance with the License.\n * You may obtain a copy of the License at\n *\n *   http://www.apache.org/licenses/LICENSE-2.0\n *\n * Unless required by applicable law or agreed to in writing, software\n * distributed under the License is distributed on an \"AS IS\" BASIS,\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n * See the License for the specific language governing permissions and\n * limitations under the License.\n */\n\nimport { DataConnectOptions, TransportOptions } from '../api/DataConnect';\nimport { Code, DataConnectError } from '../core/error';\nimport { logError } from '../logger';\n\nexport const PROD_HOST = 'firebasedataconnect.googleapis.com';\nexport const WEBSOCKET_PATH =\n  'ws/google.firebase.dataconnect.v1.ConnectorStreamService';\n\nexport function restUrlBuilder(\n  projectConfig: DataConnectOptions,\n  transportOptions: TransportOptions\n): string {\n  const { connector, location, projectId: project, service } = projectConfig;\n  const { host, sslEnabled, port } = transportOptions;\n  const protocol = sslEnabled ? 'https' : 'http';\n  const realHost = host || PROD_HOST;\n  let baseUrl = `${protocol}://${realHost}`;\n  if (typeof port === 'number') {\n    baseUrl += `:${port}`;\n  } else if (typeof port !== 'undefined') {\n    logError('Port type is of an invalid type');\n    throw new DataConnectError(\n      Code.INVALID_ARGUMENT,\n      'Incorrect type for port passed in!'\n    );\n  }\n  return `${baseUrl}/v1/projects/${project}/locations/${location}/services/${service}/connectors/${connector}`;\n}\n\nexport function websocketUrlBuilder(\n  projectConfig: DataConnectOptions,\n  transportOptions: TransportOptions\n): string {\n  const { location, projectId, service } = projectConfig;\n  const { host, sslEnabled, port } = transportOptions;\n  const protocol = sslEnabled ? 'wss' : 'ws';\n  const realHost = host || PROD_HOST;\n  let baseUrl = `${protocol}://${realHost}`;\n  if (typeof port === 'number') {\n    baseUrl += `:${port}`;\n  } else if (typeof port !== 'undefined') {\n    logError('Port type is of an invalid type');\n    throw new DataConnectError(\n      Code.INVALID_ARGUMENT,\n      'Incorrect type for port passed in!'\n    );\n  }\n  return `${baseUrl}/${WEBSOCKET_PATH}.Connect/${projectId}/locations/${location}/services/${service}`;\n}\n\nexport function addToken(url: string, apiKey?: string): string {\n  if (!apiKey) {\n    return url;\n  }\n  const newUrl = new URL(url);\n  newUrl.searchParams.append('key', apiKey);\n  return newUrl.toString();\n}\n","/**\n * @license\n * Copyright 2024 Google LLC\n *\n * Licensed under the Apache License, Version 2.0 (the \"License\");\n * you may not use this file except in compliance with the License.\n * You may obtain a copy of the License at\n *\n *   http://www.apache.org/licenses/LICENSE-2.0\n *\n * Unless required by applicable law or agreed to in writing, software\n * distributed under the License is distributed on an \"AS IS\" BASIS,\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n * See the License for the specific language governing permissions and\n * limitations under the License.\n */\n\nimport {\n  CallerSdkType,\n  CallerSdkTypeEnum,\n  DataConnectResponse,\n  DataConnectResponseWithMaxAge,\n  AbstractDataConnectTransport,\n  SubscribeObserver\n} from '..';\nimport { DataConnectOptions, TransportOptions } from '../../api/DataConnect';\nimport { AppCheckTokenProvider } from '../../core/AppCheckTokenProvider';\nimport { Code, DataConnectError } from '../../core/error';\nimport { AuthTokenProvider } from '../../core/FirebaseAuthProvider';\nimport { addToken, restUrlBuilder } from '../../util/url';\n\nimport { dcFetch } from './fetch';\n\n/**\n * Fetch-based REST implementation of {@link AbstractDataConnectTransport}.\n * @internal\n */\nexport class RESTTransport extends AbstractDataConnectTransport {\n  constructor(\n    options: DataConnectOptions,\n    apiKey?: string | undefined,\n    appId?: string | null,\n    authProvider?: AuthTokenProvider | undefined,\n    appCheckProvider?: AppCheckTokenProvider | undefined,\n    transportOptions?: TransportOptions | undefined,\n    _isUsingGen = false,\n    _callerSdkType: CallerSdkType = CallerSdkTypeEnum.Base\n  ) {\n    super(\n      options,\n      apiKey,\n      appId,\n      authProvider,\n      appCheckProvider,\n      transportOptions,\n      _isUsingGen,\n      _callerSdkType\n    );\n  }\n\n  get endpointUrl(): string {\n    return restUrlBuilder(\n      {\n        connector: this._connectorName,\n        location: this._location,\n        projectId: this._project,\n        service: this._serviceName\n      },\n      {\n        host: this._host,\n        sslEnabled: this._secure,\n        port: this._port\n      }\n    );\n  }\n\n  invokeQuery: <Data, Variables>(\n    queryName: string,\n    body?: Variables\n  ) => Promise<DataConnectResponseWithMaxAge<Data>> = <\n    Data,\n    Variables = unknown\n  >(\n    queryName: string,\n    body: Variables\n  ) => {\n    const abortController = new AbortController();\n\n    // TODO(mtewani): Update to proper value\n    const withAuth = this.withRetry(() =>\n      dcFetch<Data, Variables>(\n        addToken(`${this.endpointUrl}:executeQuery`, this.apiKey),\n        {\n          name: this._connectorResourcePath,\n          operationName: queryName,\n          variables: body\n        },\n        abortController,\n        this.appId,\n        this._authToken,\n        this._appCheckToken,\n        this._isUsingGen,\n        this._callerSdkType,\n        this._isUsingEmulator\n      )\n    );\n    return withAuth;\n  };\n\n  invokeMutation: <Data, Variables>(\n    queryName: string,\n    body?: Variables\n  ) => Promise<DataConnectResponse<Data>> = <Data, Variables = unknown>(\n    mutationName: string,\n    body: Variables\n  ) => {\n    const abortController = new AbortController();\n    const taskResult = this.withRetry(() => {\n      return dcFetch<Data, Variables>(\n        addToken(`${this.endpointUrl}:executeMutation`, this.apiKey),\n        {\n          name: this._connectorResourcePath,\n          operationName: mutationName,\n          variables: body\n        },\n        abortController,\n        this.appId,\n        this._authToken,\n        this._appCheckToken,\n        this._isUsingGen,\n        this._callerSdkType,\n        this._isUsingEmulator\n      );\n    });\n    return taskResult;\n  };\n\n  invokeSubscribe<Data, Variables>(\n    observer: SubscribeObserver<Data>,\n    queryName: string,\n    body?: Variables\n  ): void {\n    throw new DataConnectError(\n      Code.NOT_SUPPORTED,\n      'Subscriptions are not supported using REST!'\n    );\n  }\n\n  invokeUnsubscribe<Variables>(queryName: string, body?: Variables): void {\n    throw new DataConnectError(\n      Code.NOT_SUPPORTED,\n      'Unsubscriptions are not supported using REST!'\n    );\n  }\n\n  onAuthTokenChanged(newToken: string | null): void {\n    this._authToken = newToken;\n  }\n}\n","/**\n * @license\n * Copyright 2026 Google LLC\n *\n * Licensed under the Apache License, Version 2.0 (the \"License\");\n * you may not use this file except in compliance with the License.\n * You may obtain a copy of the License at\n *\n * http://www.apache.org/licenses/LICENSE-2.0\n *\n * Unless required by applicable law or agreed to in writing, software\n * distributed under the License is distributed on an \"AS IS\" BASIS,\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n * See the License for the specific language governing permissions and\n * limitations under the License.\n */\n\nimport { FirebaseError } from '@firebase/util';\n\nimport { DataConnectOptions, TransportOptions } from '../../api/DataConnect';\nimport { AppCheckTokenProvider } from '../../core/AppCheckTokenProvider';\nimport {\n  Code,\n  DataConnectError,\n  DataConnectOperationError,\n  DataConnectOperationFailureResponse\n} from '../../core/error';\nimport { AuthTokenProvider } from '../../core/FirebaseAuthProvider';\nimport { SDK_VERSION } from '../../core/version';\nimport { logError, logDebug } from '../../logger';\nimport {\n  AbstractDataConnectTransport,\n  CallerSdkType,\n  CallerSdkTypeEnum,\n  DataConnectResponse,\n  SubscribeObserver,\n  getGoogApiClientValue\n} from '../transport';\n\nimport {\n  CancelStreamRequest,\n  DataConnectStreamRequest,\n  ExecuteStreamRequest,\n  ResumeStreamRequest,\n  StreamRequestHeaders,\n  SubscribeStreamRequest\n} from './wire';\n\n/** The Request ID of the first request over the stream */\nconst FIRST_REQUEST_ID = 1;\n\n/** Time to wait before closing an idle connection (no active subscriptions). */\nconst IDLE_CONNECTION_TIMEOUT_MS = 15 * 1000; // 15 seconds\n\n/** Initial reconnect delay in ms */\nconst INITIAL_RECONNECT_DELAY_MS = 1000; // 1 second\n/** Max reconnect delay in ms */\nconst MAX_RECONNECT_DELAY_MS = 60 * 1000; // 60 seconds\n/** Factor to multiply delay by on failure */\nconst RECONNECT_BACKOFF_FACTOR = 1.5;\n\n/**\n * A promise returned to the user when invoking an operation via {@linkcode AbstractDataConnectStreamTransport.invokeQuery | invokeQuery}\n * or {@linkcode AbstractDataConnectStreamTransport.invokeMutation | invokeMutation} and the functions\n * that resolve/reject it.\n * @interna